const lv_image_dsc_t *hidrolab_astronaut_image(uint8_t profile)
{
    switch (profile) {
        case 1: return &hidrolab_img_astronaut_girl;
        case 2: return &hidrolab_img_astronaut_neutral;
        default: return &hidrolab_img_astronaut_boy;
    }
}
const lv_image_dsc_t *hidrolab_astronaut_sleep_image(uint8_t profile)
{
    switch (profile) {
        case 1: return &hidrolab_img_astronaut_girl_sleep;
        case 2: return &hidrolab_img_astronaut_neutral_sleep;
        default: return &hidrolab_img_astronaut_boy_sleep;
    }
}
